const topics=[['Bilangan dan operasi','Pecahan, tanda negatif, urutan operasi, dan estimasi.'],['Bahasa aljabar','Kesetaraan, variabel, pangkat, akar, dan faktorisasi.'],['Persamaan dan pertidaksamaan','Makna solusi dan alasan di balik setiap langkah.'],['Koordinat dan hubungan','Garis bilangan, bidang koordinat, dan kemiringan.'],['Fungsi','Hubungkan masukan, keluaran, tabel, dan grafik.'],['Keluarga fungsi','Linear, kuadrat, polinomial, rasional, dan transformasi.'],['Eksponensial dan logaritma','Memahami pertumbuhan dan hubungan invers.'],['Trigonometri','Sudut, radian, lingkaran satuan, dan pola periodik.'],['Jembatan menuju kalkulus','Perubahan rata-rata dan perilaku fungsi.']];
const $=s=>document.querySelector(s);const storage={get(k){try{return localStorage.getItem('fondasi-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-'+k,v);return true}catch{return false}}};
function renderTopics(){const q=$('#search').value.trim().toLocaleLowerCase('id');const filtered=topics.map((t,i)=>({t,i}));$('#topics').innerHTML=filtered.map(({t,i})=>`<div class="topic ${i<=8?'available':''}"><span class="topic-num">${String(i+1).padStart(2,'0')}</span><h3>${t[0]}</h3><p>${t[1]}</p>${i===0?'<a href="bilangan.html">Baca: Bilangan dan Garis Bilangan ↗</a><a href="bilangan-real.html">Baca: Mengenali Bilangan Real ↗</a><a href="pecahan.html">Baca: Pecahan — Bagian dan Nilai ↗</a><a href="operasi-pecahan.html">Baca: Menjumlahkan dan Mengurangkan Pecahan ↗</a><a href="perkalian-pecahan.html">Baca: Perkalian Pecahan ↗</a><a href="pembagian-pecahan.html">Baca: Pembagian Pecahan ↗</a><a href="urutan-operasi.html">Baca: Urutan Operasi dan Tanda Kurung ↗</a><a href="pangkat-akar.html">Baca: Pangkat dan Akar ↗</a>':i===1?'<a href="#bacaan">Baca: Memahami Tanda Sama Dengan ↗</a><a href="variabel-ekspresi.html">Baca: Variabel dan Ekspresi Aljabar ↗</a><a href="distributif.html">Baca: Sifat Distributif dan Penyederhanaan ↗</a><a href="faktorisasi.html">Baca: Faktorisasi ↗</a><a href="bentuk-akar.html">Baca: Bentuk Akar dan Pangkat Rasional ↗</a>':i===2?'<a href="persamaan-linear.html">Baca: Persamaan Linear Satu Variabel ↗</a><a href="persamaan-pecahan-akar.html">Baca: Persamaan Pecahan dan Akar ↗</a><a href="pertidaksamaan-linear.html">Baca: Pertidaksamaan Linear Satu Variabel ↗</a><a href="pertidaksamaan-majemuk.html">Baca: Pertidaksamaan Majemuk dan Interval ↗</a>':i===3?'<a href="koordinat.html">Baca: Koordinat Kartesius ↗</a><a href="garis.html">Baca: Kemiringan dan Persamaan Garis ↗</a>':i===4?'<a href="fungsi.html">Baca: Memahami Konsep Fungsi ↗</a><a href="domain-range.html">Baca: Domain dan Range ↗</a><a href="komposisi-fungsi.html">Baca: Operasi dan Komposisi Fungsi ↗</a><a href="fungsi-invers.html">Baca: Fungsi Invers ↗</a>':i===5?'<a href="transformasi-fungsi.html">Baca: Transformasi Grafik Fungsi ↗</a><a href="fungsi-kuadrat.html">Baca: Fungsi Kuadrat ↗</a><a href="fungsi-polinomial.html">Baca: Fungsi Polinomial ↗</a><a href="fungsi-rasional.html">Baca: Fungsi Rasional ↗</a>':i===6?'<a href="fungsi-eksponensial.html">Baca: Fungsi Eksponensial ↗</a><a href="fungsi-logaritma.html">Baca: Logaritma ↗</a><a href="persamaan-eksponen-log.html">Baca: Persamaan Eksponensial dan Logaritma ↗</a>':i===7?'<a href="sudut-radian.html">Baca: Sudut dan Radian ↗</a><a href="lingkaran-satuan.html">Baca: Lingkaran Satuan, Sinus, dan Kosinus ↗</a><a href="tangen.html">Baca: Tangen dan Perbandingan Trigonometri Lainnya ↗</a><a href="grafik-trigonometri.html">Baca: Grafik Sinus dan Kosinus ↗</a><a href="persamaan-trigonometri.html">Baca: Persamaan Trigonometri Dasar ↗</a><a href="identitas-trigonometri.html">Baca: Identitas dan Rumus Trigonometri ↗</a><a href="trigonometri-invers.html">Baca: Fungsi Trigonometri Invers ↗</a><a href="penerapan-trigonometri.html">Baca: Penerapan Trigonometri pada Segitiga ↗</a>':i===8?'<a href="laju-perubahan.html">Baca: Laju Perubahan Rata-Rata ↗</a><a href="gagasan-limit.html">Baca: Memahami Gagasan Limit ↗</a><a href="limit-dasar.html">Baca: Menghitung Limit Dasar ↗</a><a href="kekontinuan.html">Baca: Kekontinuan Fungsi ↗</a><a href="limit-tak-hingga.html">Baca: Limit Tak Hingga dan Perilaku di Tak Hingga ↗</a><a href="garis-singgung.html">Baca: Dari Garis Sekan ke Garis Singgung ↗</a><a href="kesiapan-kalkulus.html">Rangkuman dan Cek Kesiapan Kalkulus ↗</a>':'<span class="status">Dalam rencana pengembangan</span>'}</div>`).join('');const cards=[...document.querySelectorAll('#topics .topic')];for(const card of cards)card.hidden=!card.textContent.toLocaleLowerCase('id').includes(q);$('#empty').hidden=cards.some(card=>!card.hidden);}
$('#search').addEventListener('input',renderTopics);renderTopics();
const readerAnchors=['bacaan','awal','konsep','eksplorasi','langkah','latihan','rangkuman'];function route(){const h=location.hash.slice(1);const reading=readerAnchors.includes(h);$('#reader').hidden=!reading;$('#home').hidden=reading;if(reading){if(h==='bacaan')window.scrollTo(0,0);else requestAnimationFrame(()=>document.getElementById(h)?.scrollIntoView());}else if(h)requestAnimationFrame(()=>document.getElementById(h)?.scrollIntoView());else window.scrollTo(0,0);}window.addEventListener('hashchange',route);route();
function balance(){const x=Number($('#xrange').value),left=x+3;$('#xvalue').value=x;$('#leftWeight').textContent=left;$('#beam').style.transform=`rotate(${(7-left)*3}deg)`;$('#equation').textContent=`${x} + 3 ${left===7?'=':left<7?'<':'>'} 7`;$('#balanceFeedback').textContent=left===7?'Seimbang! 4 + 3 = 7. Jadi, x = 4 membuat kedua ruas sama nilainya.':left<7?`Ruas kiri bernilai ${left}, lebih kecil dari 7. Apa yang terjadi jika x diperbesar?`:`Ruas kiri bernilai ${left}, lebih besar dari 7. Apa yang terjadi jika x diperkecil?`;}
$('#xrange').addEventListener('input',balance);$('#reset').addEventListener('click',()=>{$('#xrange').value=2;balance()});balance();
const questions=[{title:'1. Melengkapi kesetaraan',text:'8 + 4 = □ + 5. Berapa isi kotak?',answer:7,hint:'Hitung nilai ruas kiri. Lalu pikirkan: bilangan berapa ditambah 5 menghasilkan nilai itu?',explain:'Ruas kiri bernilai 12. Karena 7 + 5 = 12, kotak berisi 7.'},{title:'2. Mencari nilai yang belum diketahui',text:'x − 5 = 9. Berapa nilai x?',answer:14,hint:'Tambahkan 5 pada kedua ruas agar x tersisa sendiri.',explain:'Tambahkan 5 pada kedua ruas: x − 5 + 5 = 9 + 5, sehingga x = 14. Periksa: 14 − 5 = 9.'},{title:'3. Memeriksa bentuk yang berbeda',text:'15 = 6 + □. Berapa isi kotak?',answer:9,hint:'Tanda sama dengan bisa dibaca dari kedua arah. Ruas kanan perlu bernilai 15.',explain:'Karena 6 + 9 = 15, kotak berisi 9. Kesetaraan tetap benar meskipun bilangan tunggal berada di kiri.'}];const solved=new Set();
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3>${q.title}</h3><p>${q.text}</p><form data-index="${i}"><label class="small" for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" inputmode="decimal" autocomplete="off" aria-describedby="feedback${i}" required><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.explain}</p></details></div>`).join('');
document.querySelectorAll('form[data-index]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.index),raw=$('#answer'+i).value.trim().replace(',','.');const valid=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw);const ok=valid&&Number(raw)===questions[i].answer;const feedback=$('#feedback'+i);feedback.className='feedback '+(ok?'correct':'incorrect');feedback.textContent=ok?'Tepat. '+questions[i].explain:valid?'Belum tepat. Coba periksa nilai kedua ruas, atau buka petunjuk di bawah.':'Tulis satu bilangan, misalnya 7, lalu periksa lagi.';if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 3 latihan sudah dipahami.`}));
$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan di peramban ini. Salin jika ingin menyimpannya.'});
function completion(){if(storage.get('complete')==='yes'){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent='Kamu bisa membaca dan mencoba kembali kapan saja.';$('#progress').textContent='Bacaan ditandai selesai ✓';}}$('#complete').addEventListener('click',()=>{const saved=storage.set('complete','yes');$('#complete-note').textContent=saved?'Selesai. Kemajuan tersimpan di peramban ini.':'Selesai. Kemajuan belum bisa disimpan di peramban ini.';$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#progress').textContent='Bacaan ditandai selesai ✓';});completion();
